import React, { useState, useRef, ReactNode, useEffect } from 'react';

interface TiltCardProps {
  children: ReactNode;
  className?: string;
  intensity?: number;
  glowColor?: string;
}

const TiltCard: React.FC<TiltCardProps> = ({ 
  children, 
  className = "", 
  intensity = 15,
  glowColor = "rgba(59, 130, 246, 0.15)"
}) => {
  const cardRef = useRef<HTMLDivElement>(null);
  const [rotate, setRotate] = useState({ x: 0, y: 0 });
  const [glow, setGlow] = useState({ x: 0, y: 0, opacity: 0 });
  const [effectiveIntensity, setEffectiveIntensity] = useState(intensity);

  useEffect(() => {
    const handleResize = () => {
      const width = window.innerWidth;
      if (width < 640) {
        // Disable tilt on mobile
        setEffectiveIntensity(0);
      } else if (width < 1024) {
        // Reduce intensity on tablets
        setEffectiveIntensity(intensity * 0.4);
      } else {
        // Full intensity on desktop
        setEffectiveIntensity(intensity);
      }
    };

    handleResize(); // Initial check
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [intensity]);

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!cardRef.current || effectiveIntensity === 0) return;

    const rect = cardRef.current.getBoundingClientRect();
    const width = rect.width;
    const height = rect.height;

    // Calculate mouse position relative to card center
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;

    const centerX = width / 2;
    const centerY = height / 2;

    const rotateY = ((mouseX - centerX) / centerX) * effectiveIntensity;
    const rotateX = ((centerY - mouseY) / centerY) * effectiveIntensity;

    setRotate({ x: rotateX, y: rotateY });
    setGlow({ x: mouseX, y: mouseY, opacity: 1 });
  };

  const handleMouseLeave = () => {
    setRotate({ x: 0, y: 0 });
    setGlow(prev => ({ ...prev, opacity: 0 }));
  };

  return (
    <div
      ref={cardRef}
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      className={`relative transition-transform duration-500 ease-out will-change-transform ${className}`}
      style={{
        perspective: "1000px",
        transform: effectiveIntensity > 0 ? `rotateX(${rotate.x}deg) rotateY(${rotate.y}deg)` : 'none',
      }}
    >
      {/* Spotlight Effect Overlay - Only visible if tilt is active or on desktop */}
      <div 
        className="absolute inset-0 pointer-events-none rounded-[inherit] z-10 transition-opacity duration-500"
        style={{
          opacity: effectiveIntensity > 0 ? glow.opacity : 0,
          background: `radial-gradient(circle at ${glow.x}px ${glow.y}px, ${glowColor}, transparent 80%)`,
        }}
      />

      {/* Border Glow Enhancement */}
      <div 
        className="absolute -inset-[1px] pointer-events-none rounded-[inherit] z-0 transition-opacity duration-500"
        style={{
          opacity: effectiveIntensity > 0 ? glow.opacity : 0,
          background: `radial-gradient(circle at ${glow.x}px ${glow.y}px, rgba(255,255,255,0.1), transparent 40%)`,
        }}
      />

      <div className="relative z-20 h-full">
        {children}
      </div>
    </div>
  );
};

export default TiltCard;

import React, { useState, useEffect } from 'react';
import { ArrowUp } from 'lucide-react';

const ScrollToTopButton: React.FC = () => {
  const [isVisible, setIsVisible] = useState(false);

  // Show button when page is scrolled down
  const toggleVisibility = () => {
    if (window.pageYOffset > 400) {
      setIsVisible(true);
    } else {
      setIsVisible(false);
    }
  };

  const scrollToTop = () => {
    window.scrollTo({
      top: 0,
      behavior: 'smooth',
    });
  };

  useEffect(() => {
    window.addEventListener('scroll', toggleVisibility);
    return () => window.removeEventListener('scroll', toggleVisibility);
  }, []);

  return (
    <div className={`fixed bottom-8 right-8 z-50 transition-all duration-500 transform ${isVisible ? 'translate-y-0 opacity-100 scale-100' : 'translate-y-10 opacity-0 scale-50 pointer-events-none'}`}>
      <button
        onClick={scrollToTop}
        aria-label="Scroll to top"
        className="group relative p-4 rounded-full glass border-blue-500/30 text-blue-400 hover:text-white hover:border-blue-500 hover:scale-110 transition-all duration-300 shadow-2xl shadow-blue-950/20 active:scale-95 overflow-hidden"
      >
        {/* Animated Glow Effect */}
        <div className="absolute inset-0 bg-blue-600/0 group-hover:bg-blue-600/20 transition-colors duration-500"></div>

        {/* Icon */}
        <ArrowUp size={24} className="relative z-10 transition-transform duration-500 group-hover:-translate-y-1" />

        {/* Pulse ring for visibility */}
        <div className="absolute inset-0 rounded-full border border-blue-500/0 group-hover:animate-ping opacity-20"></div>
      </button>
    </div>
  );
};

export default ScrollToTopButton;

